 began=time.process_time();a=read(D/'analysis.json');matrix=a['matrix_results'];allrows=a['results'];ledger=read(D/'budget.json');parts=[];costs={};tag=sys.argv[1] if len(sys.argv)>1 else 'report-replay-export-v1'
